impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        if n <= 1 {
            return 0;
        }
        let mut prefix = vec![0i32; n + 1];
        for i in 0..n {
            prefix[i + 1] = prefix[i] + stone_value[i];
        }
        let mut dp = vec![vec![0i32; n]; n];
        for len in 2..=n {
            for l in 0..=n - len {
                let r = l + len - 1;
                let mut best = 0i32;
                for k in l..r {
                    let sum_left = prefix[k + 1] - prefix[l];
                    let sum_right = prefix[r + 1] - prefix[k + 1];
                    let val = if sum_left < sum_right {
                        sum_left + dp[l][k]
                    } else if sum_left > sum_right {
                        sum_right + dp[k + 1][r]
                    } else {
                        sum_left + dp[l][k].max(dp[k + 1][r])
                    };
                    if val > best {
                        best = val;
                    }
                }
                dp[l][r] = best;
            }
        }
        dp[0][n - 1]
    }
}

